def generator(rng):
    # Randomly generate parameters, retrying until the instance is numerically nontrivial and valid.
    def sample_q(rng):
        if rng.random() < 0.4:
            return 1.0
        # Choose from rational values away from the poles to ensure stability
        candidates = [1/3, 2/3, 3/4, 4/5, 5/6, 9/10, 11/10, 7/6, 5/4, 3/2, 7/4, 9/8, 11/8, 13/8]
        return rng.choice(candidates)

    def compute_limit(q, b, base):
        if q == 1.0:
            # L = (1/2) * ln(base)
            return 0.5 * math.log(base)
        else:
            # L = (1/2) * (2b)^{q-1} * Gamma(1 - q) * cos(pi q / 2)
            return 0.5 * ((2.0 * b) ** (q - 1.0)) * math.gamma(1.0 - q) * math.cos(math.pi * q / 2.0)

    for _ in range(100):
        q = sample_q(rng)
        b = rng.randint(1, 9)
        base = rng.choice([2, 3, 5, 7, 10, 12])
        k = rng.choice([500, 750, 1000, 1250, 1500, 2000])
        # Validate domain
        if not (0.0 < q < 2.0):
            continue
        if base < 2:
            continue
        L = compute_limit(q, b, base)
        # Ensure positivity and nontrivial magnitude for difficulty
        if not (math.isfinite(L) and L > 0):
            continue
        val = k * L
        if val < 100 or val > 1e6:
            continue
        return {
            'exponent_q': q,
            'frequency_multiplier': b,
            'log_base': base,
            'scale_factor': k
        }
    # Fallback (should rarely happen): provide a safe default
    return {
        'exponent_q': 1.0,
        'frequency_multiplier': 3,
        'log_base': 10,
        'scale_factor': 1000
    }

